import {createAsset,assetSuffix} from './asset-documents.js';
import {makeStarterScene} from './scene-templates.js';
import {defaultsForObject,addSceneComponent} from './scene-components.js';
import {makeBehaviorNode,makeState,makeSequenceTrack} from './gameplay-assets.js';
export function gameplayTemplate(name,dimension){
  const scene=makeStarterScene(name,dimension),twoD=dimension==='2d',folder='Assets/Gameplay/',files={},put=(kind,name,data)=>{const path=folder+name+assetSuffix[kind];files[path]=data;return path;};
  const object=(id,kind,position)=>({id,name:id,kind,group:'WORLD',position,rotation:[0,0,0],scale:[1,1,1],visible:true,components:defaultsForObject(kind)}),p=(o,type)=>o.components.find(c=>c.type===type).properties;
  const player=scene.objects.find(o=>o.id==='Player');player.position=twoD?[3,3,.1]:[3,1,3];player.tags=['Team.Player'];addSceneComponent(player,'PerceptionSource');if(twoD){player.components=player.components.filter(c=>c.type!=='CharacterMovement2D');addSceneComponent(player,'TopDownMovement2D').properties.autoPossess=true;p(player,'Rigidbody2D').useGravity=false;scene.objects=scene.objects.filter(o=>['Player','Camera'].includes(o.id));Object.assign(p(scene.objects.find(o=>o.id==='Camera'),'Camera'),{followTarget:'',followOffset:[0,0,12]});scene.objects.find(o=>o.id==='Camera').position=[0,0,12];}
  const npc=object('AI Agent',twoD?'character2d':'character',[-3,twoD?0:1,0]);if(twoD){p(npc,'Rigidbody2D').useGravity=false;p(npc,'CharacterMovement2D').gravity=0;p(npc,'SpriteRenderer').color=[.32,.72,.67,1];}npc.tags=['Team.Enemy'];const navigation=object('Navigation','navigation',[0,0,0]);p(navigation,'NavigationGrid').plane=twoD?'XY':'XZ';p(navigation,'NavigationGrid').extent=[8,8,8];addSceneComponent(npc,'NavigationAgent');addSceneComponent(npc,'AIPerception').properties.plane=twoD?'XY':'XZ';npc.rotation=twoD?[0,0,0]:[0,45,0];const wall=object('Wall',twoD?'sprite':'cube',[0,twoD?-1:0,0]);wall.scale=twoD?[1,2,1]:[1,2,3];if(twoD)p(wall,'SpriteRenderer').color=[.32,.38,.44,1];
  const bb=createAsset('blackboard','BB_Agent');bb.keys.push({name:'Goal',type:'vec3',value:[3,twoD?0:1,0]});const bbPath=put('blackboard','BB_Agent',bb),tree=createAsset('behaviortree','BT_Agent');tree.blackboard=bbPath;const seq=makeBehaviorNode('sequence',220,170),move=makeBehaviorNode('moveTo',100,320),wait=makeBehaviorNode('wait',340,320);move.properties.key='Goal';wait.properties.duration=1;seq.children=[move.id,wait.id];tree.nodes.push(seq,move,wait);tree.nodes[0].children=[seq.id];addSceneComponent(npc,'BehaviorTree').properties.asset=put('behaviortree','BT_Agent',tree);
  const fsm=createAsset('statemachine','FSM_Agent'),patrol=makeState('Patrol',380,160);fsm.states[0].duration=1;patrol.duration=2;fsm.states.push(patrol);fsm.transitions=[{id:'idle_patrol',from:fsm.initial,to:patrol.id,hasExitTime:true,exitTime:1,event:'',conditions:[]},{id:'patrol_idle',from:patrol.id,to:fsm.initial,hasExitTime:true,exitTime:1,event:'',conditions:[]}];addSceneComponent(npc,'StateMachine').properties.asset=put('statemachine','FSM_Agent',fsm);
  const effect=object('Particles','particles',[-3,2,0]);p(effect,'ParticleSystem').shape=twoD?'circle':'cone';const animation=createAsset('animation','AN_Pulse');animation.timeline.length=2;animation.timeline.lastKeyframe=false;animation.timeline.tracks=[{id:'scale',name:'Scale',type:'vec3',interpolation:'linear',keys:[{time:0,value:[1,1,1]},{time:1,value:[1.5,1.5,1.5]},{time:2,value:[1,1,1]}]}];const clip=put('animation','AN_Pulse',animation),montage=createAsset('montage','AM_Pulse');montage.length=2;montage.loop=true;montage.clips=[{id:'pulse',clip,start:0,duration:2,sourceStart:0,rate:1,slot:'DefaultSlot'}];montage.notifies=[{id:'pulse_notify',time:1,event:'OnPulse'}];Object.assign(addSceneComponent(effect,'MontagePlayer').properties,{asset:put('montage','AM_Pulse',montage),autoPlay:true});
  const sequence=createAsset('sequenceasset','LS_Effects');sequence.length=6;sequence.loop=true;const track=makeSequenceTrack('position');track.target=effect.id;track.keys=[{time:0,value:[-3,2,0]},{time:3,value:[3,2,0]},{time:6,value:[-3,2,0]}];sequence.tracks=[track];const director=object('Sequence Director','empty',[0,0,0]);Object.assign(addSceneComponent(director,'SequencePlayer').properties,{asset:put('sequenceasset','LS_Effects',sequence),autoPlay:true});scene.objects.push(npc,navigation,wall,effect,director);return {scene,files};
}
